function trier_tableau(arr) {
    if (arr.length <= 1) return arr;

    // Insertion Sort — O(N²) mais sans utiliser .sort()
    const result = [...arr];
    for (let i = 1; i < result.length; i++) {
        let key = result[i];
        let j = i - 1;
        while (j >= 0 && result[j] > key) {
            result[j + 1] = result[j];
            j--;
        }
        result[j + 1] = key;
    }

    return result;
}
```

