function medianeDeuxTries(a, b) {
    const m = a.length;
    const n = b.length;

    // Cas particuliers
    if (m === 0) return b[Math.floor(n / 2)];
    if (n === 0) return a[Math.floor(m / 2)];

    let lo = Math.min(a[0], b[0]);
    let hi = Math.max(a[m - 1], b[n - 1]);

    while (lo <= hi) {
        const midA = Math.floor((lo + hi) / 2);
        const midB = midA + m - n;

        if (midB > n || a[midA] < b[midB - 1]) {
            lo = midA + 1;
        } else if (midA > m || b[midB] < a[midA - 1]) {
            hi = midB - 1;
        } else {
            // Cas pair — prendre la moyenne des deux médianes
            const leftMax = Math.max(midA > 0 ? a[midA - 1] : -Infinity, 
                                     midB > 0 ? b[midB - 1] : -Infinity);
            const rightMin = Math.min(midA < m ? a[midA] : Infinity, 
                                      midB < n ? b[midB] : Infinity);

            return (leftMax + rightMin) / 2;
        }
    }

    // Cas impair — retourner le plus petit des deux médianes
    const leftMax = Math.max(midA > 0 ? a[midA - 1] : -Infinity, 
                             midB > 0 ? b[midB - 1] : -Infinity);
    return leftMax;
