    // Algorithme de recherche binaire sur le plus petit tableau pour couper en O(log(min(n, m)))
    const n = a.length;
    const m = b.length;

    let lo = 0;
    let hi = n;

    while (lo <= hi) {
        const partitionA = Math.floor((lo + hi) / 2);
        const partitionB = Math.floor((n + m + 1) / 2 - partitionA);

        // Cas de base : tableau vide
        if (partitionA === 0 && partitionB === 0) {
            return b[0];
        }
        if (partitionA === n) {
            return b[partitionB - 1];
        }
        if (partitionB === 0) {
            return a[partitionA - 1];
        }

        const maxLeftA = partitionA > 0 ? a[partitionA - 1] : -Infinity;
        const minRightA = partitionA < n ? a[partitionA] : Infinity;
        const maxLeftB = partitionB > 0 ? b[partitionB - 1] : -Infinity;
        const minRightB = partitionB < m ? b[partitionB] : Infinity;

        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            // Cas pair
            if ((n + m) % 2 === 0) {
                return Math.max(maxLeftA, maxLeftB);
            } else {
                return Math.min(minRightA, minRightB);
