tiers.rawResponse:
---
1. **Tache 3A — Dernier élément**  
   ```javascript
   function dernierElement(tableau) {
     return tableau[tableau.length - 1];
   }
   ```

2. **Tache 3B — Compter jusqu'à N**  
   ```javascript
   function compterJusqua(n) {
     if (n < 1) return [];
     let result = [];
     for (let i = 1; i <= n; i++) {
       result.push(i);
     }
     return result;
   }
   ```

3. **Tache 3C — Remplacer lettre**  
   ```javascript
   function remplacerLettre(mot, ancienne, nouvelle) {
     let resultat = "";
     for (let i = 0; i < mot.length; i++) {
       resultat += (mot[i] === ancienne ? nouvelle : mot[i]);
     }
     return resultat;
   }
   ```

4. **Tache 3D — Somme tableau**  
   ```javascript
   function sommeTableau(tableau) {
     let total = 0;
     for (let i = 0; i < tableau.length; i++) {
       total += tableau[i];
     }
     return total;
   }
   ```

5. **Tache 3E — Contient 'a'**  
   ```javascript
   function contientA(mot) {
     for (let i = 0; i < mot.length; i++) {
       if (mot[i].toLowerCase() === "a") return true;
     }
     return false;
   }
   ```

6. **Exercice algorithmique — Parenthèses valides**  
   ```javascript
   function validerParentheses(s) {
     let pile = [];
     for (let i = 0; i < s.length; i++) {
       if (s[i] === "(") pile.push("(");
       else if (s[i] === ")") {
         if (pile.length > 0 && pile[pile.length - 1] === "(") pile.pop();
         else return false;
       }
     }
     return pile.length === 0;
   }
   ```

7. **Exercice algorithmique — Fibonacci**  
   ```javascript
   function fibonacci(n) {
     if (n <= 1) return n;
     let a = 0, b = 1, resultat = 0;
     for (let i = 2; i <= n; i++) {
       resultat = a + b;
       a = b;
       b = resultat;
     }
     return resultat;
   }
   ```

8. **Exercice algorithmique — Mots uniques**  
   ```javascript
   function motsUniques(s) {
     let ensemble = new Set();
     for (let i = 0; i < s.length; i++) {
       if (!/\s/.test(s[i])) ensemble.add(s[i]);
     }
     return ensemble.size;
